import assert from 'node:assert/strict';
import SuperJSON from './dist/index.js';
import { normalizeErrorStackOptions } from './dist/error-options.js';
import { processStackString, processStackFrames } from './dist/error-stack.js';
assert.equal(normalizeErrorStackOptions(null), undefined);
for (const mode of ['off','string','frames']) {
 const s = new SuperJSON({errorStack:{mode, includeCauses:'deep', sanitizeMessage:true}}); s.allowErrorProps('stack','stackFrames');
 const e = new Error('email x@y.com', {cause:new Error('https://example.com')}); e.stack='Error: x\n    at /a/b.js:1:2';
 const r=s.serialize(e); assert.equal(r.meta.values[0], mode === 'off' ? 'Error' : mode === 'string' ? 'Error/stack' : 'Error/frames'); assert.equal(r.json.message,'email [redacted]'); assert.equal(r.json.cause.message,'[redacted]');
 assert.equal('stack' in r.json, mode==='string'); assert.equal('stackFrames' in r.json, mode==='frames');
 const p=s.parse(s.stringify([new Map([['e',e]]), new Set([e])])); assert(p[0].get('e') instanceof Error); assert(p[0].get('e').cause instanceof Error);
}
const o=normalizeErrorStackOptions({mode:'string',stripInternalFrames:'node',maxStackLines:2}); const stack='Error: x\n  at node:internal/foo\n  at /x/y.js'; assert.equal(processStackString(stack,o),'Error: x'); assert.equal(processStackFrames(stack,o)[1].raw,'at /x/y.js');
const legacy=new SuperJSON(); const cause={message:'plain'}; assert.deepEqual(legacy.parse(legacy.stringify(new Error('x',{cause}))).cause,cause);
const s=new SuperJSON({errorStack:{mode:'frames',includeCauses:'deep'}}); s.allowErrorProps('stackFrames'); const e=new Error('x'); e.cause=e; assert.doesNotThrow(()=>s.stringify(e)); s.registerErrorStackProcessor('Error',v=>({...v, extra:42})); assert.equal(s.serialize(e).json.extra,42);
console.log('Focused checks passed');
